// Sustituye al antiguo js/chat-asistente.js:IDIOMAS_SOPORTADOS (fichero ya eliminado).
export const IDIOMAS_CHAT = ['es', 'en', 'fr', 'it', 'nl', 'ja', 'de', 'zh', 'pl', 'pt', 'ru', 'uk'];

// Etiqueta accesible del botón-flecha que abre un enlace interno (RESPUESTAS_CHAT.*.enlace).
export const CHAT_ABRIR_ENLACE = {
    es: 'Abrir', en: 'Open', fr: 'Ouvrir', it: 'Apri', nl: 'Openen', ja: '開く',
    de: 'Öffnen', zh: '打开', pl: 'Otwórz', pt: 'Abrir', ru: 'Открыть', uk: 'Відкрити',
};

// texto puede contener marcadores {{IMG:nombre-fichero}} en cualquier punto —
// se sustituyen por la imagen correspondiente exactamente ahí, en línea con el
// texto (no todas al final). nombre-fichero es relativo a
// imagenes/imagenes-aplicación/, sin extensión (el renderizado la resuelve).
const _rChat = (porIdioma, enlace = null) => {
    const out = {};
    for (const idioma of IDIOMAS_CHAT) out[idioma] = { texto: porIdioma[idioma], enlace };
    return out;
};

